  {
    "alert_id": "HYPERTENSION_POOR_CONTROL",
    "title": "Suboptimal BP control with amlodipine",
    "message": "Patient's BP is 146/94 mmHg, indicating suboptimal control. He admits to missing doses of amlodipine while travelling. Poor adherence and uncontrolled hypertension increase cardiovascular risk and can exacerbate renal issues, especially while on TDF. The plan only refills amlodipine without addressing adherence or considering therapy intensification.",
    "issue_type": "guideline_deviation",
    "severity": "moderate",
    "recommended_action": "Address antihypertensive adherence, consider therapy adjustment or addition per hypertension guidelines to achieve target BP.",
    "citations": []
  },
  {
    "alert_id": "TDF_HYPOPHOSPHATEMIA_RISK",
    "title": "Hypophosphatemia with TDF and ibuprofen",
    "message": "Patient has low serum phosphate (0.78 mmol/L). TDF can cause renal tubular wasting and hypophosphatemia. Concurrent use of ibuprofen (an NSAID) may impair renal function, compounding this risk. Non-drug causes like poor intake or malabsorption should also be considered. The plan continues both medications without addressing the low phosphate.",
    "issue_type": "toxicity",
    "severity": "moderate",
    "recommended_action": "Evaluate cause of hypophosphatemia, consider monitoring phosphate and renal function, and review necessity of ibuprofen.",
    "citations": [
